$documents=new Documents($db,'admin');for($i=0;$i<26;$i++)$documents->upload('Original-'.$i.'.txt','Original '.$i,['title'=>'Ablage '.$i,'kind'=>'other','scope'=>'orga'],bin2hex(random_bytes(16)));$finance=$documents->upload('Bank.txt','Geschützter Bankbeleg',['title'=>'Bankbeleg','kind'=>'receipt','document_date'=>'2026-10-08'],bin2hex(random_bytes(16)));$first=$documents->page(['scope'=>'orga']);$second=$documents->page(['scope'=>'orga'],2);check($first['total']===26&&count($first['rows'])===25&&count($second['rows'])===1,'document view paginates canonical accessible records');check(!array_intersect(array_column($first['rows'],'id'),array_column($second['rows'],'id')),'stable pages neither duplicate nor omit records');$fin=$documents->page(['scope'=>'finance']);check($fin['total']===1&&$fin['rows'][0]['id']===$finance&&$documents->file($finance)['bytes']==='Geschützter Bankbeleg','finance view links to exact original file');check($documents->page(['q'=>'Bankbeleg'])['rows'][0]['id']===$finance,'central search returns the same finance document identity');check((int)$db->query('SELECT COUNT(*) FROM document_files')->fetchColumn()===27,'views do not copy document bytes');denied(fn()=>(new Documents($db,'member'))->page(['scope'=>'finance']),'document scope filter cannot grant financial rights');denied(fn()=>$documents->page([],0),'invalid document page rejected');denied(fn()=>$documents->page([],1,10000),'unbounded document page rejected');check($documents->page(['scope'=>'orga'],999)['page']===2,'page after deletions clamps to last available page');
